mapper.select:
SELECT f.id, f.org_id, f.chain_id, c.chain_name, f.type, f.action, f.before_balance, f.after_balance, f.change_amount, f.tx_hash, f.biz_no, f.create_time, f.update_time, CASE WHEN f.type = 1 THEN ( SELECT COUNT(1) FROM order_summary_detail d WHERE d.summary_id = f.biz_no ) ELSE 0 END AS user_wallet_count FROM org_prepaid_flow f LEFT JOIN sys_chain c ON c.chain_id = f.chain_id WHERE f.org_id = #{orgId}
AND f.chain_id = #{chainId}
AND f.create_time >= #{from}
AND f.create_time < #{to}
ORDER BY f.id DESC
